// Curated disease / condition / symptom dictionary for the Hospitals "Where to go for…" search
// (services/diseaseSearch.ts). Each row: canonical English name, English synonyms + everyday words,
// Telugu (script + common Telugu-in-English spellings), Hindi (Devanagari + common spellings), and the
// ordered list of specialities to see. `emergency` marks red-flag conditions (call 108 / 112).
// This is a "which department" guide only: it never diagnoses and is not medical advice.

export type Speciality =
  | 'Cardiology'
  | 'Cardiothoracic Surgery'
  | 'Emergency Medicine'
  | 'Endocrinology'
  | 'General Medicine'
  | 'General Surgery'
  | 'Nephrology'
  | 'Urology'
  | 'Oncology'
  | 'Neurology'
  | 'Neurosurgery'
  | 'Psychiatry'
  | 'Pulmonology'
  | 'Gastroenterology'
  | 'Hepatology'
  | 'Liver Transplant'
  | 'Orthopaedics'
  | 'Rheumatology'
  | 'Dermatology'
  | 'Ophthalmology'
  | 'ENT'
  | 'Dentistry'
  | 'Obstetrics & Gynaecology'
  | 'Paediatrics'
  | 'Neonatology'
  | 'Infectious Diseases'
  | 'Haematology'
  | 'Plastic Surgery'
  | 'Vascular Surgery'
  | 'Physical Medicine & Rehabilitation'
  | 'Geriatrics';

export interface Disease {
  id: string;
  en: string;
  aliases: string[];
  te: string[]; // Telugu script first (shown in the app), then Telugu-in-English spellings
  hi: string[]; // Devanagari first (shown in the app), then Hindi-in-English spellings
  specialities: Speciality[];
  emergency?: true;
}

const SP: Record<string, Speciality> = {
  CAR: 'Cardiology',
  CTS: 'Cardiothoracic Surgery',
  EM: 'Emergency Medicine',
  END: 'Endocrinology',
  GM: 'General Medicine',
  GS: 'General Surgery',
  NEP: 'Nephrology',
  URO: 'Urology',
  ONC: 'Oncology',
  NEU: 'Neurology',
  NSG: 'Neurosurgery',
  PSY: 'Psychiatry',
  PUL: 'Pulmonology',
  GAS: 'Gastroenterology',
  HEP: 'Hepatology',
  LT: 'Liver Transplant',
  ORT: 'Orthopaedics',
  RHE: 'Rheumatology',
  DER: 'Dermatology',
  OPH: 'Ophthalmology',
  ENT: 'ENT',
  DEN: 'Dentistry',
  OBG: 'Obstetrics & Gynaecology',
  PED: 'Paediatrics',
  NEO: 'Neonatology',
  ID: 'Infectious Diseases',
  HEM: 'Haematology',
  PLS: 'Plastic Surgery',
  VAS: 'Vascular Surgery',
  PMR: 'Physical Medicine & Rehabilitation',
  GER: 'Geriatrics',
};

const split = (s: string): string[] =>
  s
    .split('|')
    .map(x => x.trim())
    .filter(Boolean);

// Compact row: id, English, aliases, Telugu, Hindi ('|' separated), speciality codes (space separated)
const R = (id: string, en: string, aliases: string, te: string, hi: string, sp: string): Disease => ({
  id,
  en,
  aliases: split(aliases),
  te: split(te),
  hi: split(hi),
  specialities: sp.split(' ').map(c => {
    const s = SP[c];
    if (!s) throw new Error(`diseases.ts: unknown speciality code ${c} in ${id}`);
    return s;
  }),
});
// Red-flag (emergency) row
const E = (id: string, en: string, aliases: string, te: string, hi: string, sp: string): Disease => ({ ...R(id, en, aliases, te, hi, sp), emergency: true });

